    /*check user access shift */
    public function check_access($user_id) {
        $access_times = $this->Tbl_shift_model->get_access_time($user_id);

        if ($access_times) {
            foreach ($access_times as $access_time) {
                $shifts = array(
                    (object) array('shift_start_time' => $access_time->shift_start_time, 'shift_end_time' => $access_time->shift_end_time)
                );

                if (check_access_time($access_time->start_date, $access_time->end_date, $shifts)) {
                    echo "Access granted";
                    return;
                }
            }
        }

        echo "Access denied";
    }

    public function set_access_time($data) { //echo '<pre>';print_r($data); die;
        $admin_id = $this->input->post('admin_id');
        $start_date = $this->input->post('start_date');
        $end_date = $this->input->post('end_date');
        $start_time = $this->input->post('start_time');
        $end_time = $this->input->post('end_time');

        $result = $this->AccessTime_model->set_access_time($admin_id, $start_date, $end_date, $start_time, $end_time);

        if ($result) {
            echo "Access time set successfully";
        } else {
            echo "Failed to set access time";
        }
        
    }

