        //     redirect('shift_master');
        // }
        // else
        //     show_error('The tbl_shift you are trying to delete does not exist.');

         // Call the model function to delete the shift and its timing
         $result = $this->Tbl_shift_model->delete_shift_with_timing($id);

         if ($result) {
             // If successful, set success message
             $this->session->set_flashdata('message', 'Shift and timing deleted successfully.');
         } else {
